<script>
(()=>{'use strict';
const API='<?= BASE_URL ?>/api/scheduling/calendar.php';
window.addEventListener('error',e=>{document.documentElement.dataset.ciError=e.message||'Unknown script error'});window.addEventListener('unhandledrejection',e=>{document.documentElement.dataset.ciError=e.reason?.message||String(e.reason||'Unhandled request error')});
const steps=[['fa-plug','Access Integration'],['fa-calendar-plus','Schedule & Users'],['fa-sliders','Settings'],['fa-eye','Preview Events'],['fa-google','Connect Account'],['fa-arrows-rotate','Export / Sync'],['fa-circle-check','Confirmation'],['fa-gears','Manage']];
const defaults={include_subject:true,include_section:true,include_room:true,include_faculty:true,include_class_type:true,include_description:true,timezone:'Asia/Manila',color:'#1769e0'};
const state={step:1,maxStep:1,data:null,selectedSchedule:null,recipientType:'Teacher',recipientKeys:[],settings:{...defaults},method:'ICS',name:'',dateFrom:'',dateTo:'',events:[],integration:null,history:[],result:null};
const el=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const iconMap={'fa-plug':'plug-connected','fa-calendar-plus':'calendar-plus','fa-sliders':'adjustments-horizontal','fa-eye':'eye','fa-google':'brand-google','fa-arrows-rotate':'refresh','fa-circle-check':'circle-check','fa-gears':'settings','fa-calendar-days':'calendar','fa-clock':'clock','fa-triangle-exclamation':'alert-triangle','fa-brands fa-google':'brand-google','fa-file-arrow-down':'file-download','fa-envelope-open-text':'mail-opened','fa-shield-halved':'shield-check','fa-list-check':'list-check','fa-plus':'plus','fa-gear':'settings','fa-circle-xmark':'circle-x','fa-link-slash':'unlink','fa-file-lines':'file-text','fa-arrow-right':'arrow-right','fa-calendar-check':'calendar-check','fa-star':'star','fa-book-open':'book','fa-lock':'lock','fa-calendar-xmark':'calendar-off','fa-arrow-up-right-from-square':'external-link','fa-chalkboard-user':'presentation','fa-people-group':'users-group','fa-graduation-cap':'school','fa-door-open':'door','fa-users':'users','fa-arrow-left':'arrow-left','fa-book':'book','fa-tags':'tags','fa-align-left':'align-left','fa-share-nodes':'share','fa-wand-magic-sparkles':'wand','fa-calendar-day':'calendar-event','fa-file-pen':'file-pencil','fa-link':'link','fa-download':'download','fa-floppy-disk':'device-floppy','fa-check':'check','fa-receipt':'receipt','fa-print':'printer','fa-clock-rotate-left':'history','fa-pen':'pencil','fa-rotate':'refresh','fa-circle-info':'info-circle','fa-spinner':'loader-2'};
function icon(name,extra=''){const spin=name.includes('fa-spin');const key=name.replace(/\s*fa-spin\s*/,'').trim();return `<i class="ti ti-${iconMap[key]||'circle'} ${spin?'ci-icon-spin':''} ${extra}"></i>`}
function alertMsg(msg,kind='info'){const x=el('ciAlert');x.className=`alert alert-${kind} mt-3`;x.innerHTML=`${icon(kind==='danger'?'fa-triangle-exclamation':kind==='success'?'fa-circle-check':'fa-circle-info','me-2')}<span>${esc(msg)}</span>`;x.classList.remove('d-none');x.scrollIntoView({behavior:'smooth',block:'nearest'})}
function clearAlert(){el('ciAlert').classList.add('d-none')}
async function req(action,opt={}){const method=opt.method||'GET';const response=await fetch(`${API}?action=${encodeURIComponent(action)}${opt.query||''}`,{method,headers:method==='POST'?{'Content-Type':'application/json'}:{},body:method==='POST'?JSON.stringify(opt.body||{}):undefined});const type=response.headers.get('content-type')||'';const data=type.includes('json')?await response.json():null;if(!response.ok||!data?.ok)throw new Error(data?.error||'The request could not be completed.');return data}
function setStep(n){state.step=n;state.maxStep=Math.max(state.maxStep,n);clearAlert();renderSteps();render()}
function renderSteps(){el('ciSteps').innerHTML=steps.map((s,i)=>{const n=i+1;const cls=n===state.step?'active':n<state.maxStep?'done':'';return `<button type="button" class="ci-step ${cls}" data-step="${n}" ${n>state.maxStep?'disabled':''}><span class="num">${n}</span><small>${icon(s[0],'me-1')}${esc(s[1])}</small></button>`}).join('');el('ciSteps').querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(+b.dataset.step))}
function panel(title,subtitle,headIcon,body,footer=''){return `<section class="ci-panel"><header class="ci-panel-head"><span class="ci-head-icon">${icon(headIcon)}</span><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div></header><div class="ci-panel-body">${body}</div>${footer?`<footer class="ci-footer-actions">${footer}</footer>`:''}</section>`}
function status(s){return `<span class="ci-status ${esc(s).replace(' ','\ ')}">${icon(s==='Synced'?'fa-circle-check':s==='Failed'?'fa-circle-xmark':s==='Disconnected'?'fa-link-slash':'fa-clock')} ${esc(s)}</span>`}
function payload(){return {id:state.integration?.id||0,name:state.name,schedule_key:state.selectedSchedule?.key||'',date_from:state.dateFrom,date_to:state.dateTo,recipient_keys:state.recipientKeys,method:state.method,settings:state.settings}}
function busy(btn,on,label='Working…'){if(!btn)return;btn.disabled=on;if(on){btn.dataset.old=btn.innerHTML;btn.innerHTML=`${icon('fa-spinner fa-spin','me-2')}${label}`}else if(btn.dataset.old)btn.innerHTML=btn.dataset.old}
function dashboard(){const d=state.data,s=d.stats;const cards=[['fa-calendar-days',s.total,'Integrations'],['fa-circle-check',s.synced,'Synced'],['fa-clock',s.pending,'Pending / Draft'],['fa-triangle-exclamation',s.failed,'Failed']];let body=`<div class="row g-3 mb-4">${cards.map(c=>`<div class="col-6 col-lg-3"><div class="ci-stat">${icon(c[0])}<div><strong>${c[1]}</strong><span>${c[2]}</span></div></div></div>`).join('')}</div>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="ci-method ci-google"><div class="icon">${icon('fa-brands fa-google')}</div><h6 class="fw-bold">Google Calendar</h6><p class="small text-muted">Secure account authorization and repeatable event synchronization.</p><button class="btn btn-sm btn-outline-primary ci-start" data-method="Google">${icon('fa-link','me-1')} Start Google Sync</button></div></div><div class="col-md-4"><div class="ci-method ci-ics"><div class="icon">${icon('fa-file-arrow-down')}</div><h6 class="fw-bold">ICS Export</h6><p class="small text-muted">Download a standard calendar file for Outlook, Apple Calendar, or Google Calendar.</p><button class="btn btn-sm btn-outline-success ci-start" data-method="ICS">${icon('fa-download','me-1')} Create ICS Export</button></div></div><div class="col-md-4"><div class="ci-method ci-outlook"><div class="icon">${icon('fa-envelope-open-text')}</div><h6 class="fw-bold">Outlook / Apple</h6><p class="small text-muted">Use the portable ICS option—no separate account connection is required.</p><button class="btn btn-sm btn-outline-primary ci-start" data-method="ICS">${icon('fa-arrow-right','me-1')} Use ICS</button></div></div></div>
<div class="ci-note mb-4">${icon('fa-shield-halved','me-2')}This subsystem reads published scheduling data. Schedule corrections remain in Teacher Mapping, Room Availability, Exam Timetable, or the appropriate source module.</div>
<div class="d-flex align-items-center justify-content-between mb-2"><h6 class="fw-bold mb-0">${icon('fa-list-check','me-2 text-primary')}Recent integrations</h6><button class="btn btn-sm btn-primary ci-start" data-method="ICS">${icon('fa-plus','me-1')} New Integration</button></div>${integrationCards(d.integrations)}`;
el('ciStage').innerHTML=panel('Access Calendar Integration','Choose a distribution method or manage an existing connection.','fa-plug',body);document.querySelectorAll('.ci-start').forEach(b=>b.onclick=()=>startNew(b.dataset.method));bindManage()}
function integrationCards(rows){if(!rows.length)return `<div class="ci-empty">${icon('fa-calendar-xmark')}No calendar integrations yet. Create one from a published schedule.</div>`;return `<div class="row g-3">${rows.map(r=>`<div class="col-md-6 col-xl-4"><article class="ci-integration"><div class="d-flex justify-content-between gap-2"><div><small class="text-primary fw-bold">${esc(r.reference_no||'Draft')}</small><h6 class="fw-bold my-1">${esc(r.name)}</h6></div>${status(r.status)}</div><div class="small text-muted mb-2">${icon(r.method==='Google'?'fa-brands fa-google':'fa-file-lines','me-1')} ${esc(r.method)} · ${esc(r.schedule_type)} · ${r.event_count} event(s)</div><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-primary ci-manage" data-id="${r.id}">${icon('fa-gear','me-1')} Manage</button>${r.status==='Needs Resync'?`<span class="small text-warning align-self-center">${icon('fa-arrows-rotate')} Re-sync needed</span>`:''}</div></article></div>`).join('')}</div>`}
function startNew(method){state.method=method;state.selectedSchedule=null;state.recipientKeys=[];state.settings={...defaults};state.integration=null;state.history=[];state.events=[];state.result=null;state.name='';state.dateFrom='';state.dateTo='';state.maxStep=2;setStep(2)}
function scheduleUsers(){const schedules=state.data.schedules;let body=`<div class="row g-4"><div class="col-lg-6"><h6 class="fw-bold">${icon('fa-calendar-check','me-2 text-primary')}Select a published schedule</h6>${schedules.length?`<div class="row g-2">${schedules.map(s=>`<div class="col-12"><article class="ci-schedule ${state.selectedSchedule?.key===s.key?'selected':''}" data-key="${esc(s.key)}"><div class="d-flex justify-content-between"><span class="type">${icon(s.type==='Exam'?'fa-file-pen':s.type==='Special'?'fa-star':'fa-book-open','me-1')}${esc(s.type)}</span><span class="badge bg-success-subtle text-success">Published</span></div><h6>${esc(s.title)}</h6><p>${esc(s.academic_year||'')} · ${esc(s.semester||'')} · ${s.entry_count} source record(s) · ${esc(s.scope)}</p></article></div>`).join('')}</div>`:`<div class="ci-empty border rounded-3">${icon('fa-lock')}No published schedules are available. Validate and publish a schedule before calendar distribution.<div class="mt-3"><a class="btn btn-sm btn-outline-primary" href="<?= BASE_URL ?>/modules/scheduling/?page=published-schedule">${icon('fa-arrow-up-right-from-square','me-1')} Go to Published Schedule</a></div></div>`}</div>
<div class="col-lg-6"><div class="d-flex justify-content-between align-items-center"><h6 class="fw-bold mb-0">${icon('fa-users','me-2 text-primary')}Select recipient scope</h6><span class="badge bg-primary-subtle text-primary">${state.recipientKeys.length} selected</span></div><div class="ci-rec-tabs my-3">${Object.keys(state.data.recipients).map(t=>`<button class="ci-rec-tab ${state.recipientType===t?'active':''}" data-type="${t}">${icon(t==='Teacher'?'fa-chalkboard-user':t==='Section'?'fa-people-group':t==='Program'?'fa-graduation-cap':'fa-door-open','me-1')}${t}</button>`).join('')}</div><input id="ciRecSearch" class="form-control form-control-sm mb-2" placeholder="Search ${esc(state.recipientType.toLowerCase())}…"><div class="d-flex justify-content-end mb-2"><button id="ciSelectAll" class="btn btn-sm btn-link text-decoration-none">Select visible</button><button id="ciClearRec" class="btn btn-sm btn-link text-decoration-none text-secondary">Clear</button></div><div class="ci-rec-list" id="ciRecList"></div></div></div>`;
const footer=`<button class="btn btn-outline-secondary" id="ciBack1">${icon('fa-arrow-left','me-2')}Back</button><button class="btn btn-primary" id="ciToSettings">Continue to Settings ${icon('fa-arrow-right','ms-2')}</button>`;el('ciStage').innerHTML=panel('Select Schedule and Users','Choose published data and the faculty, section, program, or room scope.','fa-calendar-plus',body,footer);renderRecipients();document.querySelectorAll('.ci-schedule').forEach(x=>x.onclick=()=>chooseSchedule(x.dataset.key));document.querySelectorAll('.ci-rec-tab').forEach(x=>x.onclick=()=>{state.recipientType=x.dataset.type;scheduleUsers()});el('ciRecSearch').oninput=renderRecipients;el('ciSelectAll').onclick=()=>{visibleRecipients().forEach(r=>{if(!state.recipientKeys.includes(r.key))state.recipientKeys.push(r.key)});scheduleUsers()};el('ciClearRec').onclick=()=>{state.recipientKeys=[];scheduleUsers()};el('ciBack1').onclick=()=>setStep(1);el('ciToSettings').onclick=()=>{if(!state.selectedSchedule)return alertMsg('Select a published schedule first.','warning');if(!state.recipientKeys.length)return alertMsg('Select at least one recipient or calendar scope.','warning');setStep(3)}}
function visibleRecipients(){const q=(el('ciRecSearch')?.value||'').toLowerCase();return state.data.recipients[state.recipientType].filter(r=>(r.label+' '+r.detail).toLowerCase().includes(q))}
function renderRecipients(){const list=el('ciRecList');if(!list)return;const rows=visibleRecipients();list.innerHTML=rows.length?rows.map(r=>`<div class="ci-rec-row"><input class="form-check-input ci-rec" type="checkbox" data-key="${esc(r.key)}" id="rec-${btoa(unescape(encodeURIComponent(r.key))).replace(/=/g,'')}" ${state.recipientKeys.includes(r.key)?'checked':''}><label for="rec-${btoa(unescape(encodeURIComponent(r.key))).replace(/=/g,'')}"><strong>${esc(r.label)}</strong><span>${esc(r.detail)}</span></label></div>`).join(''):`<div class="ci-empty py-4">No matching recipients.</div>`;list.querySelectorAll('.ci-rec').forEach(c=>c.onchange=()=>{if(c.checked&&!state.recipientKeys.includes(c.dataset.key))state.recipientKeys.push(c.dataset.key);if(!c.checked)state.recipientKeys=state.recipientKeys.filter(k=>k!==c.dataset.key);const badge=document.querySelector('.bg-primary-subtle');if(badge)badge.textContent=state.recipientKeys.length+' selected'})}
function chooseSchedule(key){state.selectedSchedule=state.data.schedules.find(s=>s.key===key)||null;if(state.selectedSchedule){state.name=`${state.selectedSchedule.title} — ${state.selectedSchedule.academic_year||''} ${state.selectedSchedule.semester||''}`.trim();state.dateFrom=state.selectedSchedule.date_from;state.dateTo=state.selectedSchedule.date_to}scheduleUsers()}
function settings(){const s=state.settings;const fields=[['include_subject','fa-book','Subject code & title'],['include_section','fa-users','Section'],['include_room','fa-door-open','Room'],['include_faculty','fa-chalkboard-user','Faculty / proctor'],['include_class_type','fa-tags','Class type'],['include_description','fa-align-left','Description / remarks']];const colors=['#1769e0','#10a567','#6f42c1','#f59e0b','#dc3545','#64748b'];let body=`<div class="row g-4"><div class="col-lg-7"><div class="mb-3"><label class="form-label fw-bold">Calendar name <span class="text-danger">*</span></label><input id="ciName" class="form-control" maxlength="150" value="${esc(state.name)}"></div><div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label fw-bold">Start date</label><input id="ciFrom" type="date" class="form-control" value="${esc(state.dateFrom)}"></div><div class="col-md-6"><label class="form-label fw-bold">End date</label><input id="ciTo" type="date" class="form-control" value="${esc(state.dateTo)}"></div></div><label class="form-label fw-bold">Event details</label><div class="row g-2">${fields.map(f=>`<div class="col-sm-6"><div class="ci-check"><input class="form-check-input ci-field me-2" type="checkbox" id="${f[0]}" data-field="${f[0]}" ${s[f[0]]?'checked':''}><label for="${f[0]}">${icon(f[1],'me-1 text-primary')}${f[2]}</label></div></div>`).join('')}</div><div class="row g-3 mt-2"><div class="col-md-6"><label class="form-label fw-bold">Time zone</label><select id="ciTimezone" class="form-select">${state.data.timezones.map(z=>`<option ${s.timezone===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label fw-bold d-block">Event color</label><div class="d-flex gap-2 pt-1">${colors.map(c=>`<button type="button" class="ci-color ${s.color===c?'active':''}" data-color="${c}" style="background:${c}" title="${c}"></button>`).join('')}</div></div></div></div>
<div class="col-lg-5"><h6 class="fw-bold">${icon('fa-share-nodes','me-2 text-primary')}Export method</h6><div class="ci-method ci-ics mb-3 ${state.method==='ICS'?'selected':''}" data-method="ICS"><div class="icon">${icon('fa-file-arrow-down')}</div><h6 class="fw-bold">One-time ICS Export</h6><p class="small text-muted mb-0">Download a standards-based file. No external account access is required.</p></div><div class="ci-method ci-google ${state.method==='Google'?'selected':''}" data-method="Google"><div class="icon">${icon('fa-brands fa-google')}</div><h6 class="fw-bold">Google Calendar Sync</h6><p class="small text-muted mb-1">Create or update events through an authorized Google account.</p>${state.data.google.configured?`<span class="badge bg-success-subtle text-success">${icon('fa-circle-check')} Server configured</span>`:`<span class="badge bg-warning-subtle text-warning">${icon('fa-triangle-exclamation')} Setup required</span>`}</div></div></div>`;
const footer=`<button class="btn btn-outline-secondary" id="ciBack2">${icon('fa-arrow-left','me-2')}Back</button><button type="button" class="btn btn-primary" id="ciToPreview" onclick="window.ciGeneratePreview(event)">Generate Preview ${icon('fa-wand-magic-sparkles','ms-2')}</button>`;el('ciStage').innerHTML=panel('Configure Calendar Settings','Choose event content, date range, appearance, and delivery method.','fa-sliders',body,footer);document.querySelectorAll('.ci-field').forEach(c=>c.onchange=()=>state.settings[c.dataset.field]=c.checked);document.querySelectorAll('.ci-color').forEach(c=>c.onclick=()=>{state.settings.color=c.dataset.color;settings()});document.querySelectorAll('.ci-method[data-method]').forEach(m=>m.onclick=()=>{state.method=m.dataset.method;settings()});el('ciBack2').onclick=()=>setStep(2)}
function pullSettings(){state.name=el('ciName')?.value.trim()||state.name;state.dateFrom=el('ciFrom')?.value||state.dateFrom;state.dateTo=el('ciTo')?.value||state.dateTo;state.settings.timezone=el('ciTimezone')?.value||state.settings.timezone}
async function preview(e){let btn=el('ciToPreview');try{btn=(e&&e.currentTarget)||btn;pullSettings();busy(btn,true,'Generating…');const d=await req('preview',{method:'POST',body:payload()});state.events=d.events;state.maxStep=4;setStep(4)}catch(err){alertMsg(err.message||'The preview could not be generated.','danger');busy(btn,false)}}
window.ciGeneratePreview=preview;
function previewPage(){let body=`<div class="row g-3 mb-3"><div class="col-md-4"><div class="ci-stat">${icon('fa-calendar-day')}<div><strong>${state.events.length}</strong><span>Calendar events</span></div></div></div><div class="col-md-4"><div class="ci-stat">${icon('fa-users')}<div><strong>${state.recipientKeys.length}</strong><span>Recipient scopes</span></div></div></div><div class="col-md-4"><div class="ci-stat">${icon(state.method==='Google'?'fa-brands fa-google':'fa-file-arrow-down')}<div><strong style="font-size:1rem">${esc(state.method)}</strong><span>Distribution method</span></div></div></div></div><div class="ci-note mb-3">${icon('fa-eye','me-2')}Preview only. No calendar events have been exported or synchronized yet.</div><div class="ci-preview-wrap"><table class="table table-hover ci-preview-table"><thead><tr><th>Date</th><th>Time</th><th>Event</th><th>Section</th><th>Room</th><th>Faculty</th><th>Source</th></tr></thead><tbody>${state.events.slice(0,100).map(x=>`<tr><td>${esc(new Date(x.date+'T00:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}))}</td><td class="text-nowrap">${esc(x.start_time)}–${esc(x.end_time)}</td><td><strong>${esc(x.summary)}</strong></td><td>${esc(x.section_code||'—')}</td><td>${esc(x.room_code||'—')}</td><td>${esc(x.teacher_name||'—')}</td><td><span class="ci-source">${icon(x.source==='Exam'?'fa-file-pen':x.source==='Special'?'fa-star':'fa-book-open')}${esc(x.source)}</span></td></tr>`).join('')}</tbody></table>${state.events.length>100?`<div class="small text-muted">Showing the first 100 of ${state.events.length} events.</div>`:''}</div>`;const footer=`<button class="btn btn-outline-secondary" id="ciBack3">${icon('fa-arrow-left','me-2')}Adjust Settings</button><button class="btn btn-primary" id="ciSaveConfig">Confirm & Continue ${icon('fa-arrow-right','ms-2')}</button>`;el('ciStage').innerHTML=panel('Preview Calendar Events','Verify dates, times, subjects, sections, rooms, and faculty before distribution.','fa-eye',body,footer);el('ciBack3').onclick=()=>setStep(3);el('ciSaveConfig').onclick=saveConfiguration}
async function saveConfiguration(e){const btn=e.currentTarget;busy(btn,true,'Saving…');try{const d=await req('save',{method:'POST',body:payload()});state.integration=d.integration;state.events=d.events;state.maxStep=5;setStep(5)}catch(err){alertMsg(err.message,'danger');busy(btn,false)}}
function connectPage(){const google=state.method==='Google';let body;if(google){body=`<div class="text-center py-3"><div class="ci-success-mark" style="background:linear-gradient(145deg,#4285f4,#1769d2)">${icon('fa-brands fa-google')}</div><h4 class="fw-bold mt-3">Connect Google Calendar</h4><p class="text-muted mx-auto" style="max-width:600px">Authorize event access for this integration. SMS2 stores tokens encrypted and uses them only to create or update this integration’s calendar events.</p>${state.data.google.configured?`<div class="ci-note success mx-auto mb-3" style="max-width:600px">${icon('fa-shield-halved','me-2')}Google OAuth is configured. You will be redirected to Google for consent.</div><button id="ciConnectGoogle" class="btn btn-primary btn-lg">${icon('fa-brands fa-google','me-2')}Connect with Google</button>`:`<div class="ci-note warn mx-auto" style="max-width:680px">${icon('fa-triangle-exclamation','me-2')}Google sync is not enabled on this server. Configure <code>SMS2_GOOGLE_CALENDAR_CLIENT_ID</code> and <code>SMS2_GOOGLE_CALENDAR_CLIENT_SECRET</code>, then return here. You may go back and choose ICS now.</div>`}</div>`}else{body=`<div class="text-center py-3"><div class="ci-success-mark" style="background:linear-gradient(145deg,#1bae6b,#07834c)">${icon('fa-file-arrow-down')}</div><h4 class="fw-bold mt-3">No account connection required</h4><p class="text-muted">ICS is portable and can be imported into Google Calendar, Outlook, Apple Calendar, and compatible calendar applications.</p><div class="ci-note success mx-auto" style="max-width:620px">${icon('fa-lock','me-2')}The source schedule remains read-only. The file is generated from the latest published data at download time.</div></div>`}const footer=`<button class="btn btn-outline-secondary" id="ciBack4">${icon('fa-arrow-left','me-2')}Back</button><button class="btn btn-primary" id="ciToExport" ${google?'disabled':''}>Continue to Export ${icon('fa-arrow-right','ms-2')}</button>`;el('ciStage').innerHTML=panel(google?'Connect Google Account':'ICS Export Ready',google?'Authorize secure calendar event access.':'Proceed without an external account.','fa-link',body,footer);el('ciBack4').onclick=()=>setStep(4);if(!google)el('ciToExport').disabled=false;el('ciToExport').onclick=()=>setStep(6);if(el('ciConnectGoogle'))el('ciConnectGoogle').onclick=connectGoogle}
async function connectGoogle(e){const btn=e.currentTarget;busy(btn,true,'Opening Google…');try{const d=await req('google_auth_url',{query:`&id=${state.integration.id}`});location.href=d.url}catch(err){alertMsg(err.message,'danger');busy(btn,false)}}
function exportPage(){const connected=state.integration?.status==='Connected'||state.integration?.status==='Synced'||state.integration?.status==='Needs Resync';let body=`<div class="row justify-content-center"><div class="col-lg-8"><div class="ci-note mb-3">${icon('fa-shield-halved','me-2')}A final server-side publication check runs immediately before ${state.method==='Google'?'synchronization':'file generation'}.</div><div class="ci-integration p-4"><div class="d-flex justify-content-between flex-wrap gap-2"><div><span class="small text-primary fw-bold">${esc(state.integration?.reference_no||'')}</span><h4 class="fw-bold mb-1">${esc(state.name)}</h4><p class="text-muted mb-0">${esc(state.selectedSchedule?.type)} · ${state.events.length} event(s) · ${state.recipientKeys.length} recipient scope(s)</p></div>${status(state.integration?.status||'Draft')}</div><hr><div class="row g-3 small"><div class="col-sm-4"><strong class="d-block">Period</strong>${esc(state.dateFrom)} to ${esc(state.dateTo)}</div><div class="col-sm-4"><strong class="d-block">Time zone</strong>${esc(state.settings.timezone)}</div><div class="col-sm-4"><strong class="d-block">Method</strong>${esc(state.method)}</div></div></div><div class="text-center mt-4">${state.method==='ICS'?`<button id="ciDoExport" class="btn btn-success btn-lg">${icon('fa-download','me-2')}Generate & Download ICS</button>`:connected?`<button id="ciDoSync" class="btn btn-primary btn-lg">${icon('fa-arrows-rotate','me-2')}Synchronize Calendar</button>`:`<div class="ci-note warn">${icon('fa-link-slash','me-2')}Google account is not connected. Return to the previous step to authorize it.</div>`}</div></div></div>`;const footer=`<button class="btn btn-outline-secondary" id="ciBack5">${icon('fa-arrow-left','me-2')}Back</button><button class="btn btn-outline-primary" id="ciSaveLater">${icon('fa-floppy-disk','me-2')}Save for Later</button>`;el('ciStage').innerHTML=panel('Export / Sync Calendar','Distribute the current published schedule using the configured method.','fa-arrows-rotate',body,footer);el('ciBack5').onclick=()=>setStep(5);el('ciSaveLater').onclick=()=>{alertMsg('Integration saved as a draft. You can continue from Manage Integration.','success');setTimeout(()=>setStep(1),700)};if(el('ciDoExport'))el('ciDoExport').onclick=downloadIcs;if(el('ciDoSync'))el('ciDoSync').onclick=syncGoogle}
async function downloadIcs(e){const btn=e.currentTarget;busy(btn,true,'Generating…');try{const r=await fetch(`${API}?action=export&id=${state.integration.id}`);if(!r.ok){let d={};try{d=await r.json()}catch(_){}throw new Error(d.error||'ICS export failed.')}const blob=await r.blob();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(state.name||'schedule').replace(/[^a-z0-9_-]+/gi,'-').toLowerCase()+'.ics';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);state.result={mode:'ICS',events:state.events.length};state.integration.status='Synced';state.maxStep=7;setStep(7);await reloadData()}catch(err){alertMsg(err.message,'danger');busy(btn,false)}}
async function syncGoogle(e){const btn=e.currentTarget;busy(btn,true,'Synchronizing…');try{const d=await req('sync',{method:'POST',body:{id:state.integration.id}});state.result={mode:'Google',...d.result};state.integration=d.integration;state.maxStep=7;setStep(7);await reloadData()}catch(err){alertMsg(err.message,'danger');busy(btn,false)}}
function confirmation(){const r=state.result||{};let body=`<div class="text-center py-3"><div class="ci-success-mark">${icon('fa-check')}</div><h3 class="fw-bold text-success mt-3">${state.method==='Google'?'Calendar Synchronized Successfully!':'Calendar Exported Successfully!'}</h3><p class="text-muted">${state.method==='Google'?'Published events were created or updated in the connected Google Calendar.':'The ICS file was generated from current published schedule data.'}</p><div class="ci-integration text-start mx-auto mt-4" style="max-width:680px"><h6 class="fw-bold mb-3">${icon('fa-receipt','me-2 text-primary')}Distribution summary</h6><div class="row g-3 small"><div class="col-sm-6"><strong>Reference</strong><div>${esc(state.integration?.reference_no)}</div></div><div class="col-sm-6"><strong>Calendar</strong><div>${esc(state.name)}</div></div><div class="col-sm-6"><strong>Method</strong><div>${esc(state.method)}</div></div><div class="col-sm-6"><strong>Events</strong><div>${r.events??state.events.length}</div></div>${state.method==='Google'?`<div class="col-sm-3"><strong>Created</strong><div>${r.created||0}</div></div><div class="col-sm-3"><strong>Updated</strong><div>${r.updated||0}</div></div><div class="col-sm-3"><strong>Unchanged</strong><div>${r.unchanged||0}</div></div><div class="col-sm-3"><strong>Failed</strong><div>${r.failed||0}</div></div>`:''}</div></div></div>`;const footer=`<button class="btn btn-outline-secondary" id="ciPrint">${icon('fa-print','me-2')}Print Confirmation</button><div class="d-flex gap-2"><button class="btn btn-outline-primary" id="ciAnother">${icon('fa-plus','me-2')}Sync Another</button><button class="btn btn-primary" id="ciManageNow">Manage Integration ${icon('fa-arrow-right','ms-2')}</button></div>`;el('ciStage').innerHTML=panel('Success and Confirmation','Distribution is complete and recorded in integration history.','fa-circle-check',body,footer);el('ciPrint').onclick=()=>window.print();el('ciAnother').onclick=()=>startNew('ICS');el('ciManageNow').onclick=()=>manage(state.integration.id)}
async function manage(id){try{const d=await req('integration',{query:`&id=${id}`});state.integration=d.integration;state.history=d.history;state.name=d.integration.name;state.method=d.integration.method;state.recipientKeys=d.integration.recipient_keys;state.settings={...defaults,...d.integration.settings};state.dateFrom=d.integration.date_from;state.dateTo=d.integration.date_to;state.selectedSchedule=state.data.schedules.find(s=>s.key===d.integration.schedule_key)||{key:d.integration.schedule_key,type:d.integration.schedule_type,title:d.integration.name,academic_year:d.integration.academic_year,semester:d.integration.semester};state.maxStep=8;setStep(8)}catch(err){alertMsg(err.message,'danger')}}
function managePage(){const i=state.integration;let body=`<div class="row g-4"><div class="col-lg-7"><div class="ci-integration p-4"><div class="d-flex justify-content-between flex-wrap gap-2"><div><small class="text-primary fw-bold">${esc(i.reference_no)}</small><h4 class="fw-bold mb-1">${esc(i.name)}</h4><p class="text-muted mb-0">${esc(i.method)} · ${esc(i.schedule_type)} · ${esc(i.academic_year||'')} ${esc(i.semester||'')}</p></div>${status(i.status)}</div><hr><div class="row g-3 small"><div class="col-sm-4"><strong>Events</strong><div>${i.event_count}</div></div><div class="col-sm-4"><strong>Last sync</strong><div>${esc(i.last_sync_at||'Not yet synced')}</div></div><div class="col-sm-4"><strong>Google account</strong><div>${esc(i.google_account_email||'Not connected')}</div></div><div class="col-sm-6"><strong>Date range</strong><div>${esc(i.date_from)} to ${esc(i.date_to)}</div></div><div class="col-sm-6"><strong>Created by</strong><div>${esc(i.created_by_name)}</div></div></div>${i.last_error?`<div class="ci-note warn mt-3">${icon('fa-triangle-exclamation','me-2')}${esc(i.last_error)}</div>`:''}</div><div class="d-flex flex-wrap gap-2 mt-3"><button class="btn btn-primary" id="ciResync">${icon(i.method==='Google'?'fa-arrows-rotate':'fa-download','me-2')}${i.method==='Google'?'Re-sync Now':'Export Latest ICS'}</button><button class="btn btn-outline-primary" id="ciEdit">${icon('fa-pen','me-2')}Edit Configuration</button><button class="btn btn-outline-secondary" id="ciPrintManage">${icon('fa-print','me-2')}Print</button>${i.method==='Google'&&i.status!=='Disconnected'?`<button class="btn btn-outline-danger" id="ciDisconnect">${icon('fa-link-slash','me-2')}Disconnect</button>`:''}</div></div><div class="col-lg-5"><h6 class="fw-bold">${icon('fa-clock-rotate-left','me-2 text-primary')}Integration history</h6><div class="ci-rec-list" style="max-height:430px">${state.history.length?state.history.map(h=>`<div class="ci-rec-row align-items-start"><span class="ci-head-icon" style="width:32px;height:32px;font-size:.8rem">${icon(h.action.includes('Sync')?'fa-arrows-rotate':h.action.includes('Export')?'fa-download':h.action.includes('Disconnect')?'fa-link-slash':'fa-pen')}</span><div><strong>${esc(h.action)}</strong><span>${esc(h.detail)}<br>${esc(h.changed_by_name)} · ${esc(h.created_at)}</span></div></div>`).join(''):`<div class="ci-empty py-4">No history yet.</div>`}</div></div></div>`;const footer=`<button class="btn btn-outline-secondary" id="ciDashboard">${icon('fa-arrow-left','me-2')}Back to Dashboard</button><button class="btn btn-primary" id="ciNew">${icon('fa-plus','me-2')}New Integration</button>`;el('ciStage').innerHTML=panel('Manage Integration','Re-sync current published data, review history, or remove authorization.','fa-gears',body,footer);el('ciDashboard').onclick=()=>setStep(1);el('ciNew').onclick=()=>startNew('ICS');el('ciPrintManage').onclick=()=>window.print();el('ciEdit').onclick=()=>{state.maxStep=3;setStep(3)};el('ciResync').onclick=i.method==='Google'?syncGoogle:downloadIcs;if(el('ciDisconnect'))el('ciDisconnect').onclick=disconnect}
async function disconnect(e){if(!confirm('Disconnect this Google account? Existing events in Google Calendar will not be deleted.'))return;const btn=e.currentTarget;busy(btn,true,'Disconnecting…');try{const d=await req('disconnect',{method:'POST',body:{id:state.integration.id}});alertMsg(d.message,'success');await reloadData();await manage(state.integration.id)}catch(err){alertMsg(err.message,'danger');busy(btn,false)}}
function bindManage(){document.querySelectorAll('.ci-manage').forEach(b=>b.onclick=()=>manage(+b.dataset.id))}
function render(){if(!state.data)return;({1:dashboard,2:scheduleUsers,3:settings,4:previewPage,5:connectPage,6:exportPage,7:confirmation,8:managePage}[state.step]||dashboard)()}
async function reloadData(){const d=await req('bootstrap');state.data=d;return d}
async function init(){renderSteps();try{await reloadData();const q=new URLSearchParams(location.search);if(q.get('connected')==='1'&&q.get('integration')){await manage(+q.get('integration'));state.maxStep=6;setStep(6);history.replaceState({},'',location.pathname)}else render()}catch(err){el('ciStage').innerHTML=panel('Calendar Integration unavailable','The workflow could not be loaded.','fa-triangle-exclamation',`<div class="ci-note warn">${esc(err.message)}</div><button class="btn btn-primary mt-3" onclick="location.reload()">${icon('fa-rotate','me-2')}Retry</button>`);alertMsg(err.message,'danger')}}
init();
})();
</script>
<?php require_once __DIR__ . '/../../../includes/layout-end.php'; ?>
